        actionType: "create",
        content: `from mcp.server.fastmcp import FastMCP, Context\nfrom pydantic import BaseModel, Field\nimport sqlite3\nimport json\nfrom typing import List\n\n# Initialize Server\nmcp = FastMCP("KnowledgeBase")\nDB_PATH = "knowledge.db"\n\n# --- Database Management ---\ndef get_db():\n    conn = sqlite3.connect(DB_PATH)\n    conn.row_factory = sqlite3.Row\n    return conn\n\ndef init_db():\n    with get_db() as conn:\n        conn.execute("""\n            CREATE TABLE IF NOT EXISTS entries (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                topic TEXT NOT NULL,\n                content TEXT NOT NULL,\n                tags TEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n            )\n        """)\ninit_db()\n\n# --- Data Models ---\nclass NoteEntry(BaseModel):\n    topic: str = Field(..., description="The main topic of the note")\n    content: str = Field(..., description="The body content")\n    tags: List[str] = Field(default=[], description="List of tags for categorization")\n\n# --- Tools ---\n@mcp.tool()\nasync def add_note(ctx: Context, entry: NoteEntry) -> str:\n    """Add a new note to the knowledge base."""\n    ctx.info(f"Adding note for topic: {entry.topic}")\n    \n    try:\n        with get_db() as conn:\n            tags_json = json.dumps(entry.tags)\n            cursor = conn.execute(\n                "INSERT INTO entries (topic, content, tags) VALUES (?, ?, ?)",\n                (entry.topic, entry.content, tags_json)\n            )\n            note_id = cursor.lastrowid\n            \n        return f"Successfully added note #{note_id} to topic '{entry.topic}'."\n    except Exception as e:\n        ctx.error(f"Failed to write DB: {e}")\n        return f"Error adding note: {str(e)}"\n\n@mcp.tool()\nasync def search_notes(query: str) -> str:\n    """Search notes by topic or content."""\n    with get_db() as conn:\n        cursor = conn.execute(\n            "SELECT id, topic, content FROM entries WHERE topic LIKE ? OR content LIKE ?",\n            (f"%{query}%", f"%{query}%")\n        )\n        rows = cursor.fetchall()\n        \n    if not rows:\n        return "No matching notes found."\n        \n    results = []\n    for row in rows:\n        results.append(f"[#{row['id']}] {row['topic']}: {row['content'][:50]}...")\n    \n    return "\\n".join(results)\n\n# --- Resources ---\n@mcp.resource("kb://all_topics")\ndef list_topics() -> str:\n    """Get a list of all unique topics in the DB."""\n    with get_db() as conn:\n        rows = conn.execute("SELECT DISTINCT topic FROM entries").fetchall()\n    return "\\n".join([r['topic'] for r in rows])\n\nif __name__ == "__main__":\n    mcp.run()`,
