        id: "server-adv-weather",
        label: "Weather Agent",
        desc: "API + Caching + Progress",
        icon: <Cloud size={14} className="text-[#00e676]" />,
        tag: "Advanced",
        actionType: "create",
        content: `from mcp.server.fastmcp import FastMCP, Context\nimport httpx\nimport asyncio\nfrom datetime import datetime, timedelta\n\nmcp = FastMCP("WeatherAgent")\n\n# --- In-Memory Caching ---\n_CACHE = {}\n_CACHE_TTL = 300  # 5 minutes\n\nclass WeatherCache:\n    @staticmethod\n    def get(key):\n        if key in _CACHE:\n            data, timestamp = _CACHE[key]\n            if datetime.now() - timestamp < timedelta(seconds=_CACHE_TTL):\n                return data\n            del _CACHE[key]\n        return None\n\n    @staticmethod\n    def set(key, data):\n        _CACHE[key] = (data, datetime.now())\n\n# --- Tools ---\n@mcp.tool()\nasync def get_forecast(ctx: Context, city: str, days: int = 1) -> str:\n    """\n    Get weather forecast for a specific city.\n    Uses OpenMeteo API (no key required).\n    """\n    city = city.lower().strip()\n    cache_key = f"{city}_{days}"\n    \n    # 1. Check Cache\n    cached = WeatherCache.get(cache_key)\n    if cached:\n        ctx.info(f"Returning cached data for {city}")\n        return cached\n\n    ctx.info(f"Fetching fresh data for {city}...")\n    await ctx.report_progress(10, 100)\n\n    async with httpx.AsyncClient() as client:\n        # 2. Geocoding\n        try:\n            geo_url = f"https://geocoding-api.open-meteo.com/v1/search?name={city}&count=1&language=en&format=json"\n            geo_resp = await client.get(geo_url)\n            geo_data = geo_resp.json()\n            \n            if not geo_data.get("results"):\n                return f"Error: City '{city}' not found."\n                \n            lat = geo_data["results"][0]["latitude"]\n            lon = geo_data["results"][0]["longitude"]\n            await ctx.report_progress(50, 100)\n            \n            # 3. Weather Fetch\n            weather_url = f"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=auto&forecast_days={days}"\n            weather_resp = await client.get(weather_url)\n            weather_data = weather_resp.json()\n            \n        except Exception as e:\n            return f"API Error: {str(e)}"\n\n    # 4. Format Output\n    daily = weather_data.get("daily", {})\n    output = [f"Weather Forecast for {city.title()} ({days} days):"]\n    \n    for i in range(len(daily.get("time", []))):\n        date = daily["time"][i]\n        temp_max = daily["temperature_2m_max"][i]\n        temp_min = daily["temperature_2m_min"][i]\n        precip = daily["precipitation_sum"][i]\n        output.append(f"- {date}: High {temp_max}°C, Low {temp_min}°C, Rain {precip}mm")\n\n    result = "\\n".join(output)\n    \n    # 5. Cache result\n    WeatherCache.set(cache_key, result)\n    await ctx.report_progress(100, 100)\n    \n    return result\n\n# --- Prompts ---\n@mcp.prompt()\ndef weather_report_template(city: str) -> str:\n    """Template for generating a weather report"""\n    return f"""\n    You are a weather reporter.\n    Please use the \`get_forecast\` tool to find the weather for {city}.\n    Then, write a short, friendly summary of the weather outlook.\n    """\n\nif __name__ == "__main__":\n    mcp.run()`,
