        content: `\nimport sqlite3\n\n# Initialize DB\nconn = sqlite3.connect("mcp.db", check_same_thread=False)\nconn.execute("CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY, content TEXT)")\n\n@mcp.tool()\nasync def add_note(content: str) -> str:\n    """Save a note to the database"""\n    cursor = conn.cursor()\n    cursor.execute("INSERT INTO notes (content) VALUES (?)", (content,))\n    conn.commit()\n    return "Note saved."\n\n@mcp.resource("db://notes")\nasync def get_notes() -> str:\n    """Read all notes"""\n    cursor = conn.cursor()\n    rows = cursor.execute("SELECT content FROM notes").fetchall()\n    return "\\n".join([r[0] for r in rows])\n`,
